<template><div class="flex min-h-screen items-center justify-center bg-slate-950 p-4"><form @submit.prevent="submit" class="w-full max-w-md rounded-3xl bg-white p-8"><RouterLink to="/shop" class="text-xl font-black">Market<span class="text-indigo-600">Flow</span></RouterLink><h1 class="mt-8 text-3xl font-black">Create your account</h1><p class="mt-2 text-slate-500">One account for shopping and affiliate marketing.</p><input v-model="name" required placeholder="Full name" class="mt-6 w-full rounded-xl border p-3"/><input v-model="email" type="email" required placeholder="Email" class="mt-3 w-full rounded-xl border p-3"/><input v-model="password" type="password" required placeholder="Password" class="mt-3 w-full rounded-xl border p-3"/><p v-if="error" class="mt-3 text-sm text-red-600">{{error}}</p><button class="mt-5 w-full rounded-xl bg-indigo-600 py-3 font-bold text-white">Create account</button><RouterLink class="mt-5 block text-center text-sm text-indigo-600" to="/login">Already have an account? Sign in</RouterLink></form></div></template><script>import api from'../services/api';import{setAuth}from'../stores';export default{data(){return{name:'',email:'',password:'',error:''}},methods:{async submit(){try{const r=await api.post('/auth/register',{name:this.name,email:this.email,password:this.password});setAuth(r.data.user,r.data.token);this.$router.push('/shop')}catch(e){this.error=e.response?.data?.message||'Registration failed'}}}}</script>